using System.Security.Claims;
using Kaluz.Web.Models;using Kaluz.Web.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Authentication;using Microsoft.AspNetCore.Authentication.Cookies;
namespace Kaluz.Web.Controllers;
public class AccountController(Db db,KaluzService svc):Controller{
 [AllowAnonymous][HttpGet]public IActionResult Login()=>View(new LoginForm());
 [AllowAnonymous][HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Login(LoginForm form){if(!ModelState.IsValid)return View(form);try{var rows=db.List("SELECT u.IdUsuario,u.NombreCompleto,u.Email,u.PasswordHash,r.Nombre AS Rol FROM Usuario u JOIN Rol r ON r.IdRol=u.IdRol WHERE u.Email=@e AND u.Activo=1",Db.P("@e",form.Email));if(rows.Count==0||!KaluzService.Verify(form.Password,Convert.ToString(rows[0]["PasswordHash"])??"")){ModelState.AddModelError("","Credenciales incorrectas.");return View(form);}var u=rows[0];var claims=new[]{new Claim(ClaimTypes.NameIdentifier,Convert.ToString(u["IdUsuario"])!),new Claim(ClaimTypes.Name,Convert.ToString(u["NombreCompleto"])!),new Claim(ClaimTypes.Role,Convert.ToString(u["Rol"])!)};await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme)));db.Exec("UPDATE Usuario SET UltimoAcceso=SYSDATETIME() WHERE IdUsuario=@id",Db.P("@id",u["IdUsuario"]));return RedirectToAction("Index","Home");}catch(Exception){ModelState.AddModelError("","No se pudo iniciar sesión. Verifica que SQL Server y KaluzDB estén disponibles.");return View(form);}}
 [AllowAnonymous][HttpGet]public IActionResult Setup(){try{if(Convert.ToInt32(db.Scalar("SELECT COUNT(*) FROM Usuario"))>0)return RedirectToAction("Login");}catch{return Content("Primero ejecuta KaluzDB.sql y configura la conexión en appsettings.json.");}return View();}
 [AllowAnonymous][HttpPost][ValidateAntiForgeryToken]public IActionResult Setup(string name,string email,string password){try{if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(email)||string.IsNullOrEmpty(password)||password.Length<8)throw new Exception("Nombre, correo y contraseña de 8 caracteres como mínimo son obligatorios.");svc.Setup(name,email,password);TempData["ok"]="Cuenta administrador creada. Inicia sesión.";return RedirectToAction("Login");}catch(Exception e){ViewBag.Error=e.Message;return View();}}
 [Authorize][HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return RedirectToAction("Login");}
 [Authorize][HttpGet]public IActionResult Password()=>View(new ChangePasswordForm());
 [Authorize][HttpPost][ValidateAntiForgeryToken]public IActionResult Password(ChangePasswordForm form){if(!ModelState.IsValid)return View(form);try{svc.ChangePassword(int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!),form.Actual,form.Nueva);TempData["ok"]="Contraseña actualizada.";return RedirectToAction("Index","Home");}catch(Exception ex){ModelState.AddModelError("",ex.Message);return View(form);}}
 [AllowAnonymous]public IActionResult Denied()=>Content("No cuentas con permisos para esta operación.");
}
